pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role) public {
        bytes32 adminRole = c.getRoleAdmin(role);
        if (adminRole == role) return;
        vm.assume(role == c.PROPOSER_ROLE() || role == c.EXECUTOR_ROLE());
        assertTrue(c.hasRole(adminRole, address(this)));
    }
}
